import{_ as i,o as s,c as a,ax as t}from"./chunks/framework.Bnt0oLax.js";const u=JSON.parse('{"title":"Get Started with the CLI","description":"Install the Developer Studio CLI, pair a session with your community, scaffold your first widget, and preview it live.","frontmatter":{"description":"Install the Developer Studio CLI, pair a session with your community, scaffold your first widget, and preview it live."},"headers":[],"relativePath":"cli/getting-started.md","filePath":"cli/getting-started.md"}'),n={name:"cli/getting-started.md"};function o(r,e,l,d,p,h){return s(),a("div",null,[...e[0]||(e[0]=[t(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/getting-started.md for this page in Markdown format</div><h1 id="get-started-with-the-cli" tabindex="-1">Get Started with the CLI <a class="header-anchor" href="#get-started-with-the-cli" aria-label="Permalink to &quot;Get Started with the CLI&quot;">​</a></h1><p>In this tutorial, you will install the <strong>Developer Studio CLI</strong>, pair it with your community, scaffold a React widget, and preview it inside your community&#39;s No-Code Builder. By the end, you will have a working local development loop and know how to iterate on a widget without publishing anything.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>You need:</p><ul><li>Node.js 18 or later</li><li>A community account with developer access</li><li>Access to <strong>CLI Access</strong> under <strong>Integrations → Developer Studio</strong> in your community, so you can mint a pairing code. This surface is rolling out to pilot tenants — if you don&#39;t see it, talk to your Gainsight team about enabling it</li></ul><h2 id="_1-install-the-cli" tabindex="-1">1. Install the CLI <a class="header-anchor" href="#_1-install-the-cli" aria-label="Permalink to &quot;1. Install the CLI&quot;">​</a></h2><p>Install <code>gsds</code> globally with npm:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @gainsight-hub/developer-studio-cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>You should see a version like <code>1.2.0</code> or newer.</p><h2 id="_2-create-an-empty-project" tabindex="-1">2. Create an empty project <a class="header-anchor" href="#_2-create-an-empty-project" aria-label="Permalink to &quot;2. Create an empty project&quot;">​</a></h2><p>Create a project directory and scaffold it in one step:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-widgets</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-widgets</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>gsds init</code> writes a <code>gsds.json</code> marker at the project root, seeds empty <code>extensions_registry.json</code> and <code>connectors_registry.json</code> files, and adds a <code>.gitignore</code> that excludes <code>.gsds/</code> (CLI capture output) from your repository.</p><h2 id="_3-pair-a-session-with-your-community" tabindex="-1">3. Pair a session with your community <a class="header-anchor" href="#_3-pair-a-session-with-your-community" aria-label="Permalink to &quot;3. Pair a session with your community&quot;">​</a></h2><p>In your community admin, open <strong>Integrations → Developer Studio → CLI Access</strong>, mint a pairing code, and copy it. Then redeem it in your terminal:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PAIRING-CODE-FROM-COMMUNITY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Pairing codes are single-use and expire <strong>1 minute</strong> after they are issued, so mint the code with your terminal already open. The resulting session token is stored in your OS keychain, is tenant-scoped, and lasts about <strong>8 hours</strong>.</p><p>You can confirm the session at any time:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_4-scaffold-a-widget" tabindex="-1">4. Scaffold a widget <a class="header-anchor" href="#_4-scaffold-a-widget" aria-label="Permalink to &quot;4. Scaffold a widget&quot;">​</a></h2><p>From your project root, scaffold a React widget:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revenue-overview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --framework</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --category</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Analytics</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>gsds create</code> writes a new folder under <code>widgets/revenue-overview/</code> with a <code>widget.json</code>, a <code>package.json</code> that includes a <code>dev</code> script (required for previewing), and starter source files.</p><h2 id="_5-preview-it-in-your-community" tabindex="-1">5. Preview it in your community <a class="header-anchor" href="#_5-preview-it-in-your-community" aria-label="Permalink to &quot;5. Preview it in your community&quot;">​</a></h2><p>Start the local dev server:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>gsds preview</code> requires an active session (you just paired one). It boots each widget&#39;s <code>dev</code> script, using the package manager it detects from that widget&#39;s lockfile, and registers a preview session with your community.</p><p>Open your community, browse to a page, and open the widget picker in the No-Code Builder. Your local widgets appear alongside published ones while <code>gsds preview</code> is running. Edit files under <code>widgets/revenue-overview/</code> and the picker reflects your changes.</p><p>Stop the preview with <code>Ctrl-C</code>.</p><h2 id="what-you-learned" tabindex="-1">What you learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What you learned&quot;">​</a></h2><ul><li>How to install <code>gsds</code> and confirm it works</li><li>How to pair a session with a pairing code</li><li>How to scaffold a project and a widget</li><li>How to preview local widgets against your community</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Learn the full session model — pairing, expiry, and logout — in <a href="./authenticate.html">Authenticate</a></li><li>Add a Connector and run it against your tenant with <a href="./test-connectors.html">Test Connectors</a></li><li>See every command and flag in the <a href="./reference/commands.html">Command reference</a></li></ul>`,34)])])}const g=i(n,[["render",o]]);export{u as __pageData,g as default};
